import openpyxl, re, os
from openpyxl.utils import get_column_letter
SRC='/workspace/input.xlsx'
OUT='/workspace/output.xlsx'
wb=openpyxl.load_workbook(SRC, data_only=False)
log=[]

def colnum(s):
    n=0
    for ch in s: n=n*26+(ord(ch)-64)
    return n

def shift(f, sc, tc, r):
    dc=tc-sc
    def sh(m):
        ref=m.group(0)
        mm=re.fullmatch(r'(\$?)([A-Za-z]{1,3})(\$?)([0-9]+)', ref)
        if not mm: return ref
        pre,letters,post,rows=mm.groups()
        ncol=colnum(letters)+dc; nrow=int(rows)
        if ncol<1 or nrow<1: return '#REF!'
        return pre+get_column_letter(ncol)+post+str(nrow)
    return re.sub(r'\$?[A-Za-z]{1,3}\$?[0-9]+', sh, f)

for ws in wb.worksheets:
    if ws.title in ('Cover','ReadMeFirst','Disclaimer'): continue
    if ws.title=='Assumptions':
        cols=range(7,16)  # G:O
    elif ws.title in ('P&L','BS','CF','Reserves','Debt Schedule','Asset Schedule','Valuation'):
        cols=range(1, ws.max_column+1)
    else:
        cols=range(1, ws.max_column+1)
    for r in range(1, ws.max_row+1):
        fm={}
        for c in cols:
            v=ws.cell(r,c).value
            if isinstance(v,str) and v.startswith('='): fm[c]=v
        if not fm:
            continue
        lo=min(fm); hi=max(fm)
        if ws.title=='Assumptions':
            lo=min(lo,7); hi=max(hi,15)
        for c in range(lo, hi+1):
            if ws.cell(r,c).value is not None: continue
            left=[x for x in fm if x<c]
            right=[x for x in fm if x>c]
            if not left and not right: continue
            sc=max(left) if left else min(right)
            nf=shift(fm[sc], sc, c, r)
            if '#REF!' not in nf:
                ws.cell(r,c).value=nf
                log.append((ws.title,get_column_letter(c)+str(r),get_column_letter(sc)+str(r),nf))

wb.save(OUT)
with open('/workspace/final_changes.txt','w') as f:
    for x in log: f.write('\t'.join(map(str,x))+'\n')
print('saved', os.path.getsize(OUT), 'changes', len(log))
